export function createTileFloorTexture(){const l=document.createElement("canvas");l.width=512,l.height=512;const t=l.getContext("2d");t.fillStyle="#9b9b94",t.fillRect(0,0,512,512);const n=128,e=5;for(let a=0;a<4;a++)for(let o=0;o<4;o++){const c=214+Math.random()*18-9;t.fillStyle=`rgb(${c}, ${c}, ${c-6})`,t.fillRect(o*n+e/2,a*n+e/2,n-e,n-e);for(let d=0;d<8;d++)t.fillStyle=`rgba(120, 120, 112, ${Math.random()*.05})`,t.fillRect(o*n+e+Math.random()*(n-24),a*n+e+Math.random()*(n-24),10+Math.random()*12,10+Math.random()*12)}const r=new THREE.CanvasTexture(l);return r.wrapS=THREE.RepeatWrapping,r.wrapT=THREE.RepeatWrapping,r.repeat.set(5,9),r}export function createConcreteFloorTexture(){const l=document.createElement("canvas");l.width=512,l.height=512;const t=l.getContext("2d");t.fillStyle="#7d7f7c",t.fillRect(0,0,512,512);for(let e=0;e<4200;e++){const r=Math.random();t.fillStyle=r<.5?`rgba(50, 52, 50, ${.04+Math.random()*.08})`:`rgba(190, 192, 188, ${.04+Math.random()*.07})`;const a=1+Math.random()*2;t.fillRect(Math.random()*512,Math.random()*512,a,a)}for(let e=0;e<7;e++){const r=Math.random()*512,a=Math.random()*512,o=18+Math.random()*42,c=t.createRadialGradient(r,a,0,r,a,o);c.addColorStop(0,"rgba(28, 26, 22, 0.22)"),c.addColorStop(.7,"rgba(28, 26, 22, 0.08)"),c.addColorStop(1,"rgba(0, 0, 0, 0)"),t.fillStyle=c,t.fillRect(r-o,a-o,o*2,o*2)}t.strokeStyle="rgba(40, 42, 40, 0.35)",t.lineWidth=1;for(let e=0;e<5;e++){let r=Math.random()*512,a=Math.random()*512;t.beginPath(),t.moveTo(r,a);for(let o=0;o<6;o++)r+=(Math.random()-.5)*90,a+=(Math.random()-.5)*90,t.lineTo(r,a);t.stroke()}t.fillStyle="rgba(226, 191, 62, 0.75)",t.fillRect(150,0,10,512),t.fillRect(352,0,10,512);const n=new THREE.CanvasTexture(l);return n.wrapS=THREE.RepeatWrapping,n.wrapT=THREE.RepeatWrapping,n.repeat.set(2,3),n}export function createStuccoTexture(){const l=document.createElement("canvas");l.width=512,l.height=512;const t=l.getContext("2d");t.fillStyle="#e6dcc4",t.fillRect(0,0,512,512);for(let e=0;e<5200;e++){const r=Math.random();t.fillStyle=r<.5?`rgba(120, 108, 84, ${.04+Math.random()*.08})`:`rgba(255, 250, 236, ${.05+Math.random()*.09})`;const a=1+Math.random()*2;t.fillRect(Math.random()*512,Math.random()*512,a,a)}for(let e=0;e<14;e++){const r=Math.random()*512,a=Math.random()*512,o=40+Math.random()*90,c=t.createRadialGradient(r,a,0,r,a,o),d=Math.random()<.5;c.addColorStop(0,d?"rgba(150, 136, 106, 0.10)":"rgba(244, 238, 220, 0.12)"),c.addColorStop(1,"rgba(0, 0, 0, 0)"),t.fillStyle=c,t.fillRect(r-o,a-o,o*2,o*2)}for(let e=0;e<26;e++){const r=Math.random()*512,a=6+Math.random()*18,o=30+Math.random()*80;t.fillStyle=`rgba(96, 86, 66, ${.03+Math.random()*.05})`,t.fillRect(r,512-o,a,o)}const n=new THREE.CanvasTexture(l);return n.wrapS=THREE.RepeatWrapping,n.wrapT=THREE.RepeatWrapping,n.repeat.set(4,4),n}export function createWoodFloorTexture(){const l=document.createElement("canvas");l.width=512,l.height=512;const t=l.getContext("2d");t.fillStyle="#8B7355",t.fillRect(0,0,512,512);const n=64;for(let r=0;r<8;r++){const a=r*n,o=139+Math.random()*30-15;t.fillStyle=`rgb(${o}, ${o*.8}, ${o*.6})`,t.fillRect(a+1,0,n-2,512),t.strokeStyle="rgba(0, 0, 0, 0.1)",t.lineWidth=1;for(let c=0;c<20;c++){const d=Math.random()*512;t.beginPath(),t.moveTo(a+2,d),t.lineTo(a+n-2,d+(Math.random()*10-5)),t.stroke()}}const e=new THREE.CanvasTexture(l);return e.wrapS=THREE.RepeatWrapping,e.wrapT=THREE.RepeatWrapping,e.repeat.set(8,10),e}
